<?php require_once __DIR__.'/lib/functions.php'; $type=$_GET['type']??'zeny'; $allowed=['zeny','level','pvp','mvp']; if(!in_array($type,$allowed,true))$type='zeny'; $queries=['zeny'=>'SELECT name,base_level,job_level,zeny,point_pvp,point_mvp FROM `char` WHERE name<>\'\' ORDER BY zeny DESC LIMIT 20','level'=>'SELECT name,base_level,job_level,zeny,point_pvp,point_mvp FROM `char` WHERE name<>\'\' ORDER BY base_level DESC,job_level DESC,base_exp DESC LIMIT 20','pvp'=>'SELECT name,base_level,job_level,zeny,point_pvp,point_mvp FROM `char` WHERE name<>\'\' ORDER BY point_pvp DESC LIMIT 20','mvp'=>'SELECT name,base_level,job_level,zeny,point_pvp,point_mvp FROM `char` WHERE name<>\'\' ORDER BY point_mvp DESC LIMIT 20']; $rows=db()->query($queries[$type])->fetchAll(); require __DIR__.'/partials/header.php'; ?>
<section class="section"><div class="section-head center"><span>SERVER LEADERBOARD</span><h1>RANKING SERVER</h1><p>อัปเดตตรงจากฐานข้อมูลเซิร์ฟเวอร์</p></div><div class="tabs"><?php foreach(['zeny'=>'อันดับ Zeny','level'=>'อันดับ Level','pvp'=>'อันดับ PvP','mvp'=>'อันดับ MVP'] as $k=>$v):?><a class="<?=$type===$k?'active':''?>" href="?type=<?=$k?>"><?=$v?></a><?php endforeach;?></div><div class="table-card"><div class="table-scroll"><table><thead><tr><th>#</th><th>ชื่อตัวละคร</th><th>Base / Job</th><th>Zeny</th><th>PvP</th><th>MVP</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><span class="rank <?=($i<3)?'top':''?>"><?=$i+1?></span></td><td><b><?=e($r['name'])?></b></td><td><?=$r['base_level']?> / <?=$r['job_level']?></td><td><?=number_format($r['zeny'])?></td><td><?=number_format($r['point_pvp'])?></td><td><?=number_format($r['point_mvp'])?></td></tr><?php endforeach;?></tbody></table></div></div></section>
<?php require __DIR__.'/partials/footer.php'; ?>
